import { useCallback, useEffect, useRef, useState } from 'react';
import type { QueryGroup } from './query-model';
import { createQueryGroup } from './query-model';
import type { QueryAction, QueryReducerOptions } from './query-state';
import { areQueriesEqual, cloneQuery, isQueryGroupValue, reduceQuery } from './query-state';

export type QueryChangeHandler = (query: QueryGroup, action: QueryAction) => void;

export type UseQueryBuilderControllerOptions = {
	query: QueryGroup;
	onQueryChange: QueryChangeHandler;
	reducerOptions?: QueryReducerOptions;
};

export function useQueryBuilderController({ query, onQueryChange, reducerOptions }: UseQueryBuilderControllerOptions) {
	const dispatch = useCallback(
		(action: QueryAction) => {
			const next = reduceQuery(query, action, reducerOptions);
			if (next === query) return query;
			onQueryChange(next, action);
			return next;
		},
		[onQueryChange, query, reducerOptions],
	);
	return { query, dispatch };
}

export type QueryDraftApplyOptions = {
	force?: boolean;
};

export type UseQueryBuilderDraftOptions<TIssue = never> = {
	value: QueryGroup;
	onApply?: (query: QueryGroup) => void;
	validate?: (query: QueryGroup) => readonly TIssue[];
	reducerOptions?: QueryReducerOptions;
};

export type QueryDraftSetter = (query: QueryGroup | ((current: QueryGroup) => QueryGroup)) => void;

function prepareExternalQuery(value: unknown) {
	return isQueryGroupValue(value)
		? { query: cloneQuery(value), valid: true }
		: { query: createQueryGroup('query-invalid-external'), valid: false };
}

export function useQueryBuilderDraft<TIssue = never>({
	value,
	onApply,
	validate,
	reducerOptions,
}: UseQueryBuilderDraftOptions<TIssue>) {
	const initialRef = useRef<ReturnType<typeof prepareExternalQuery> | null>(null);
	if (!initialRef.current) initialRef.current = prepareExternalQuery(value);
	const initial = initialRef.current;
	const baselineRef = useRef<QueryGroup>(initial.query);
	const latestExternalRef = useRef<QueryGroup>(initial.query);
	const seenExternalRef = useRef<QueryGroup>(initial.query);
	const draftRef = useRef<QueryGroup>(initial.query);
	const [draft, setDraftState] = useState(initial.query);
	const [stale, setStale] = useState(false);
	const [invalidExternal, setInvalidExternal] = useState(!initial.valid);
	const staleRef = useRef(false);

	const setDraft = useCallback<QueryDraftSetter>((next) => {
		setDraftState((current) => {
			const resolved = typeof next === 'function' ? next(current) : next;
			if (!isQueryGroupValue(resolved)) return current;
			if (areQueriesEqual(current, resolved)) return current;
			const owned = cloneQuery(resolved);
			draftRef.current = owned;
			return owned;
		});
	}, []);

	useEffect(() => {
		if (!isQueryGroupValue(value)) {
			setInvalidExternal(true);
			return;
		}
		setInvalidExternal(false);
		const incoming = cloneQuery(value);
		if (areQueriesEqual(seenExternalRef.current, incoming)) return;
		seenExternalRef.current = incoming;
		latestExternalRef.current = incoming;
		const draftMatchesIncoming = areQueriesEqual(draftRef.current, incoming);
		const draftMatchesBaseline = areQueriesEqual(draftRef.current, baselineRef.current);
		const baselineMatchesIncoming = areQueriesEqual(baselineRef.current, incoming);
		if (draftMatchesIncoming || draftMatchesBaseline) {
			baselineRef.current = incoming;
			draftRef.current = incoming;
			setDraftState(incoming);
			staleRef.current = false;
			setStale(false);
		} else if (baselineMatchesIncoming) {
			staleRef.current = false;
			setStale(false);
		} else {
			staleRef.current = true;
			setStale(true);
		}
	}, [value]);

	useEffect(() => {
		if (!staleRef.current || !areQueriesEqual(draft, latestExternalRef.current)) return;
		baselineRef.current = cloneQuery(latestExternalRef.current);
		staleRef.current = false;
		setStale(false);
	}, [draft]);

	const dispatch = useCallback(
		(action: QueryAction) => {
			const current = draftRef.current;
			const next = reduceQuery(current, action, reducerOptions);
			if (next === current) return current;
			draftRef.current = next;
			setDraftState(next);
			return next;
		},
		[reducerOptions],
	);

	const reset = useCallback(() => {
		const next = cloneQuery(latestExternalRef.current);
		baselineRef.current = next;
		draftRef.current = next;
		setDraftState(next);
		staleRef.current = false;
		setStale(false);
		return next;
	}, []);

	const apply = useCallback(
		(options: QueryDraftApplyOptions = {}) => {
			if (staleRef.current && !options.force) return undefined;
			const next = cloneQuery(draftRef.current);
			onApply?.(cloneQuery(next));
			return next;
		},
		[onApply],
	);
	const overwrite = useCallback(() => apply({ force: true }), [apply]);

	return {
		draft,
		dispatch,
		setDraft,
		onQueryChange: setDraft,
		dirty: !areQueriesEqual(draft, baselineRef.current),
		stale,
		canApply: !stale,
		invalidExternal,
		issues: validate?.(draft) ?? [],
		apply,
		overwrite,
		reset,
	};
}

import { Popover as BasePopover } from '@base-ui/react/popover';
import { Check, ChevronDown, Plus, Search, X } from 'lucide-react';
import type { ComponentType, KeyboardEvent as ReactKeyboardEvent, ReactNode } from 'react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import type { QueryBuilderMessages } from './query-messages';
import type {
	QueryField,
	QueryFieldKind,
	QueryJsonPrimitive,
	QueryJsonValue,
	QueryOperator,
	QueryRule,
} from './query-model';

export type QueryFieldPickerProps = {
	fields: readonly QueryField[];
	label: ReactNode;
	searchLabel: string;
	emptyLabel: string;
	disabled?: boolean;
	invalid?: boolean;
	ariaDescribedBy?: string;
	className?: string;
	onSelect: (field: QueryField) => void;
};

export function QueryFieldPicker({
	fields,
	label,
	searchLabel,
	emptyLabel,
	disabled,
	invalid,
	ariaDescribedBy,
	className,
	onSelect,
}: QueryFieldPickerProps) {
	const [open, setOpen] = useState(false);
	const [search, setSearch] = useState('');
	const optionsRef = useRef<HTMLDivElement>(null);
	const filtered = useMemo(() => {
		const needle = search.trim().toLocaleLowerCase();
		return needle
			? fields.filter((field) =>
					`${field.label} ${field.name} ${field.group ?? ''}`.toLocaleLowerCase().includes(needle),
				)
			: [...fields];
	}, [fields, search]);
	const groups = useMemo(() => groupFields(filtered), [filtered]);
	return (
		<BasePopover.Root
			open={open}
			onOpenChange={(nextOpen) => {
				setOpen(nextOpen);
				if (!nextOpen) setSearch('');
			}}
		>
			<BasePopover.Trigger
				render={
					<button
						type='button'
						disabled={disabled || fields.length === 0}
						className={cn('btn btn-outline btn-sm min-w-0 justify-between gap-2', className)}
						aria-invalid={invalid || undefined}
						aria-describedby={ariaDescribedBy}
					/>
				}
			>
				<span className='min-w-0 truncate'>{label}</span>
				<ChevronDown aria-hidden='true' className='size-3.5 shrink-0' />
			</BasePopover.Trigger>
			<BasePopover.Portal>
				<BasePopover.Positioner align='start' sideOffset={6} className='z-60'>
					<BasePopover.Popup className='border-base-300 bg-base-100 text-base-content w-[min(22rem,calc(100vw-2rem))] rounded-md border p-2 shadow-xl outline-none'>
						<label className='input input-sm input-bordered flex w-full items-center gap-2'>
							<Search aria-hidden='true' className='text-base-content/50 size-4 shrink-0' />
							<input
								type='search'
								className='min-w-0 grow'
								aria-label={searchLabel}
								placeholder={searchLabel}
								value={search}
								onChange={(event) => setSearch(event.target.value)}
								onKeyDown={(event) => focusFirstOption(event, optionsRef.current)}
							/>
						</label>
						<div ref={optionsRef} data-query-options='' className='mt-2 max-h-72 overflow-auto'>
							{filtered.length === 0 ? (
								<div className='text-base-content/65 px-2 py-6 text-center text-sm'>{emptyLabel}</div>
							) : (
								groups.map(([group, entries]) => (
									<div key={group || 'fields'} className='py-1'>
										{group ? (
											<div className='text-base-content/65 px-2 py-1 text-[11px] font-semibold uppercase'>{group}</div>
										) : null}
										{entries.map((field) => (
											<button
												key={field.name}
												type='button'
												data-query-option='field'
												className='hover:bg-base-200 focus-visible:bg-base-200 flex w-full min-w-0 items-start rounded-sm px-2 py-2 text-left outline-none'
												onClick={() => {
													onSelect(field);
													setOpen(false);
												}}
												onKeyDown={focusAdjacentOption}
											>
												<span className='min-w-0'>
													<span className='block truncate text-sm font-medium'>{field.label}</span>
													{field.description ? (
														<span className='text-base-content/65 mt-0.5 line-clamp-2 block text-xs'>
															{field.description}
														</span>
													) : null}
												</span>
											</button>
										))}
									</div>
								))
							)}
						</div>
					</BasePopover.Popup>
				</BasePopover.Positioner>
			</BasePopover.Portal>
		</BasePopover.Root>
	);
}

function groupFields(fields: readonly QueryField[]) {
	const groups = new Map<string, QueryField[]>();
	for (const field of fields) {
		const group = field.group ?? '';
		const entries = groups.get(group) ?? [];
		entries.push(field);
		groups.set(group, entries);
	}
	return [...groups.entries()];
}

export type QueryValueEditorProps = {
	id: string;
	rule: QueryRule;
	field: QueryField;
	operator: QueryOperator;
	value: QueryJsonValue;
	disabled?: boolean;
	readOnly?: boolean;
	invalid?: boolean;
	ariaDescribedBy?: string;
	messages: QueryBuilderMessages;
	onChange: (value: QueryJsonValue) => void;
};

export type QueryValueEditorComponent = ComponentType<QueryValueEditorProps>;
export type QueryValueEditorRenderer = (props: QueryValueEditorProps) => ReactNode | undefined;

export function QueryDefaultValueEditor(props: QueryValueEditorProps) {
	const { operator, field, value, messages } = props;
	if (props.readOnly) return <QueryReadOnlyValue {...props} />;
	if (operator.cardinality === 'none') {
		return <span className='text-base-content/65 inline-flex min-h-8 items-center text-xs'>{messages.noValue}</span>;
	}
	if (operator.cardinality === 'pair') {
		const pair = Array.isArray(value) && value.length === 2 ? value : [null, null];
		return (
			<div className='grid min-w-0 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-2'>
				<ScalarEditor
					{...props}
					id={`${props.id}-start`}
					ariaLabel={messages.rangeStart}
					value={pair[0]}
					onChange={(next) => props.onChange([next, pair[1]])}
				/>
				<span aria-hidden='true' className='text-base-content/55 text-xs'>
					–
				</span>
				<ScalarEditor
					{...props}
					id={`${props.id}-end`}
					ariaLabel={messages.rangeEnd}
					value={pair[1]}
					onChange={(next) => props.onChange([pair[0], next])}
				/>
			</div>
		);
	}
	if (operator.cardinality === 'many') {
		return field.options?.length ? <MultiOptionEditor {...props} /> : <ListValueEditor {...props} />;
	}
	return <ScalarEditor {...props} ariaLabel={field.label} value={value} onChange={props.onChange} />;
}

export function QueryReadOnlyValue({ id, field, operator, value, messages, ariaDescribedBy }: QueryValueEditorProps) {
	const values = Array.isArray(value) ? value : [value];
	const label = (item: QueryJsonValue) => {
		if (typeof item === 'boolean') return item ? messages.trueLabel : messages.falseLabel;
		return field.options?.find((option) => Object.is(option.value, item))?.label ?? String(item ?? '');
	};
	const text =
		operator.cardinality === 'none'
			? messages.noValue
			: operator.cardinality === 'pair'
				? `${label(values[0])} – ${label(values[1])}`
				: values.map(label).filter(Boolean).join(', ');
	return (
		<output
			id={id}
			aria-label={field.label}
			aria-describedby={ariaDescribedBy}
			className='border-base-300 bg-base-100 flex min-h-8 w-full min-w-0 items-center rounded-sm border px-2.5 text-sm'
		>
			{text || messages.chooseValue}
		</output>
	);
}

type ScalarEditorProps = QueryValueEditorProps & {
	ariaLabel: string;
};

function ScalarEditor({
	id,
	field,
	value,
	disabled,
	invalid,
	messages,
	ariaLabel,
	ariaDescribedBy,
	onChange,
}: ScalarEditorProps) {
	const kind = field.kind === 'array' ? (field.itemKind ?? 'unknown') : field.kind;
	if (field.options?.length) {
		const selected = field.options.findIndex((option) => Object.is(option.value, value));
		return (
			<select
				id={id}
				className='select select-bordered select-sm w-full min-w-0'
				aria-label={ariaLabel}
				aria-invalid={invalid || undefined}
				aria-describedby={ariaDescribedBy}
				disabled={disabled}
				value={selected < 0 ? '' : String(selected)}
				onChange={(event) =>
					onChange(event.target.value === '' ? null : (field.options?.[Number(event.target.value)]?.value ?? null))
				}
			>
				<option value=''>{messages.chooseValue}</option>
				{withOccurrenceKeys(field.options, queryOptionKey).map(({ item: option, key }, index) => (
					<option key={key} value={index} disabled={option.disabled}>
						{option.label}
					</option>
				))}
			</select>
		);
	}
	if (kind === 'boolean') {
		return (
			<select
				id={id}
				className='select select-bordered select-sm w-full min-w-0'
				aria-label={ariaLabel}
				aria-invalid={invalid || undefined}
				aria-describedby={ariaDescribedBy}
				disabled={disabled}
				value={typeof value === 'boolean' ? String(value) : ''}
				onChange={(event) => onChange(event.target.value === '' ? null : event.target.value === 'true')}
			>
				<option value=''>{messages.chooseValue}</option>
				<option value='true'>{messages.trueLabel}</option>
				<option value='false'>{messages.falseLabel}</option>
			</select>
		);
	}
	if (kind === 'number' || kind === 'integer') {
		return (
			<NumberEditor
				id={id}
				kind={kind}
				value={value}
				disabled={disabled}
				invalid={invalid}
				ariaLabel={ariaLabel}
				ariaDescribedBy={ariaDescribedBy}
				onChange={onChange}
			/>
		);
	}
	const type = inputType(kind);
	return (
		<input
			id={id}
			type={type}
			className='input input-bordered input-sm w-full min-w-0'
			aria-label={ariaLabel}
			aria-invalid={invalid || undefined}
			aria-describedby={ariaDescribedBy}
			disabled={disabled}
			step={kind === 'datetime' ? 1 : undefined}
			placeholder={field.placeholder}
			value={formatEditorValue(value, kind)}
			onChange={(event) => onChange(parseScalar(event.target.value, kind))}
		/>
	);
}

function NumberEditor({
	id,
	kind,
	value,
	disabled,
	invalid,
	ariaLabel,
	ariaDescribedBy,
	onChange,
}: {
	id: string;
	kind: 'number' | 'integer';
	value: QueryJsonValue;
	disabled?: boolean;
	invalid?: boolean;
	ariaLabel: string;
	ariaDescribedBy?: string;
	onChange: (value: QueryJsonValue) => void;
}) {
	const [draft, setDraft] = useState(() => formatScalar(value));
	const latestValue = useRef(value);
	latestValue.current = value;
	useEffect(() => setDraft(formatScalar(value)), [value]);
	const reconcileProposal = () => {
		queueMicrotask(() => setDraft(formatScalar(latestValue.current)));
	};
	return (
		<input
			id={id}
			type='number'
			className='input input-bordered input-sm w-full min-w-0'
			aria-label={ariaLabel}
			aria-invalid={invalid || undefined}
			aria-describedby={ariaDescribedBy}
			disabled={disabled}
			step={kind === 'integer' ? 1 : 'any'}
			value={draft}
			onChange={(event) => {
				const next = event.target.value;
				setDraft(next);
				if (next === '') {
					onChange(null);
					reconcileProposal();
				} else if (isCompleteNumber(next, kind)) {
					onChange(Number(next));
					reconcileProposal();
				}
			}}
			onBlur={() => {
				const parsed = Number(draft);
				if (draft.trim() && Number.isFinite(parsed) && (kind !== 'integer' || Number.isInteger(parsed))) {
					onChange(parsed);
				}
				reconcileProposal();
			}}
		/>
	);
}

function isCompleteNumber(value: string, kind: 'number' | 'integer') {
	return kind === 'integer' ? /^[+-]?\d+$/.test(value) : /^[+-]?(?:\d+|\d+\.\d+|\.\d+)(?:[eE][+-]?\d+)?$/.test(value);
}

function MultiOptionEditor({
	field,
	value,
	disabled,
	invalid,
	ariaDescribedBy,
	messages,
	onChange,
}: QueryValueEditorProps) {
	const [open, setOpen] = useState(false);
	const [search, setSearch] = useState('');
	const [selectedOnly, setSelectedOnly] = useState(false);
	const optionsRef = useRef<HTMLDivElement>(null);
	const selected = Array.isArray(value) ? value : [];
	const options = field.options ?? [];
	const filtered = options.filter((option) => {
		const matchesSearch = option.label.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase());
		return matchesSearch && (!selectedOnly || selected.some((item) => Object.is(item, option.value)));
	});
	const toggle = (option: QueryJsonPrimitive) => {
		const exists = selected.some((item) => Object.is(item, option));
		onChange(exists ? selected.filter((item) => !Object.is(item, option)) : [...selected, option]);
	};
	return (
		<div className='min-w-0'>
			<BasePopover.Root open={open} onOpenChange={setOpen}>
				<BasePopover.Trigger
					render={
						<button
							type='button'
							className='btn btn-outline btn-sm w-full min-w-0 justify-between'
							disabled={disabled}
							aria-invalid={invalid || undefined}
							aria-describedby={ariaDescribedBy}
						/>
					}
				>
					<span className='truncate'>
						{selected.length ? messages.selectedCount(selected.length) : messages.chooseValue}
					</span>
					<ChevronDown aria-hidden='true' className='size-3.5 shrink-0' />
				</BasePopover.Trigger>
				<BasePopover.Portal>
					<BasePopover.Positioner align='start' sideOffset={6} className='z-60'>
						<BasePopover.Popup className='border-base-300 bg-base-100 w-[min(20rem,calc(100vw-2rem))] rounded-md border p-2 shadow-xl outline-none'>
							<label className='input input-sm input-bordered flex w-full items-center gap-2'>
								<Search aria-hidden='true' className='size-4' />
								<input
									type='search'
									className='min-w-0 grow'
									aria-label={messages.searchValues}
									value={search}
									onChange={(event) => setSearch(event.target.value)}
									onKeyDown={(event) => focusFirstOption(event, optionsRef.current)}
								/>
							</label>
							<div className='mt-2 flex items-center justify-between gap-2 px-1'>
								<label className='label cursor-pointer gap-2 py-1 text-xs'>
									<input
										type='checkbox'
										className='checkbox checkbox-xs'
										checked={selectedOnly}
										onChange={(event) => setSelectedOnly(event.target.checked)}
									/>
									{messages.selectedOnly}
								</label>
								<button
									type='button'
									className='btn btn-ghost btn-xs'
									disabled={selected.length === 0}
									onClick={() => onChange([])}
								>
									{messages.clearValues}
								</button>
							</div>
							<div ref={optionsRef} data-query-options='' className='mt-1 max-h-60 overflow-auto'>
								{withOccurrenceKeys(filtered, queryOptionKey).map(({ item: option, key }) => {
									const active = selected.some((item) => Object.is(item, option.value));
									return (
										<button
											key={key}
											type='button'
											data-query-option='value'
											aria-pressed={active}
											disabled={option.disabled}
											className='hover:bg-base-200 flex w-full items-center gap-2 rounded-sm px-2 py-2 text-left text-sm'
											onClick={() => toggle(option.value)}
											onKeyDown={focusAdjacentOption}
										>
											<Check aria-hidden='true' className={cn('size-4 shrink-0', !active && 'invisible')} />
											<span className='min-w-0 truncate'>{option.label}</span>
										</button>
									);
								})}
							</div>
						</BasePopover.Popup>
					</BasePopover.Positioner>
				</BasePopover.Portal>
			</BasePopover.Root>
			<ValueChips values={selected} options={options} disabled={disabled} messages={messages} onChange={onChange} />
		</div>
	);
}

function ListValueEditor({
	rule,
	field,
	value,
	disabled,
	invalid,
	ariaDescribedBy,
	messages,
	onChange,
}: QueryValueEditorProps) {
	const [draft, setDraft] = useState('');
	useEffect(() => setDraft(''), [rule.id, rule.operator]);
	const values = Array.isArray(value) ? value : [];
	const itemKind = field.kind === 'array' ? (field.itemKind ?? 'unknown') : field.kind;
	const add = () => {
		const next = parseScalar(draft, itemKind);
		if (next === null || values.some((item) => Object.is(item, next))) return;
		onChange([...values, next]);
		setDraft('');
	};
	return (
		<div className='min-w-0'>
			<div className='flex min-w-0 gap-1.5'>
				{itemKind === 'boolean' ? (
					<select
						className='select select-bordered select-sm min-w-0 flex-1'
						aria-label={messages.addValue}
						aria-invalid={invalid || undefined}
						aria-describedby={ariaDescribedBy}
						disabled={disabled}
						value={draft}
						onChange={(event) => setDraft(event.target.value)}
					>
						<option value=''>{messages.chooseValue}</option>
						<option value='true'>{messages.trueLabel}</option>
						<option value='false'>{messages.falseLabel}</option>
					</select>
				) : (
					<input
						type={inputType(itemKind)}
						className='input input-bordered input-sm min-w-0 flex-1'
						aria-label={messages.addValue}
						aria-invalid={invalid || undefined}
						aria-describedby={ariaDescribedBy}
						disabled={disabled}
						step={itemKind === 'datetime' ? 1 : undefined}
						value={draft}
						onChange={(event) => setDraft(event.target.value)}
						onKeyDown={(event) => {
							if (event.key === 'Enter') {
								event.preventDefault();
								add();
							}
						}}
					/>
				)}
				<button
					type='button'
					className='btn btn-outline btn-sm btn-square'
					title={messages.addValue}
					aria-label={messages.addValue}
					disabled={disabled || draft.trim().length === 0}
					onClick={add}
				>
					<Plus aria-hidden='true' className='size-4' />
				</button>
			</div>
			<ValueChips values={values} disabled={disabled} messages={messages} onChange={onChange} />
		</div>
	);
}

function ValueChips({
	values,
	options,
	disabled,
	messages,
	onChange,
}: {
	values: QueryJsonValue[];
	options?: readonly { value: QueryJsonPrimitive; label: string }[];
	disabled?: boolean;
	messages: QueryBuilderMessages;
	onChange: (value: QueryJsonValue) => void;
}) {
	if (!values.length) return null;
	const entries = withOccurrenceKeys(values, queryValueKey);
	return (
		<div className='mt-1.5 flex min-w-0 flex-wrap gap-1'>
			{entries.map(({ item: value, key }, index) => {
				const label = options?.find((option) => Object.is(option.value, value))?.label ?? String(value);
				return (
					<span key={key} className='badge badge-outline h-6 max-w-full gap-1 pe-1 text-xs'>
						<span className='truncate'>{label}</span>
						<button
							type='button'
							className='hover:bg-base-200 grid size-4 shrink-0 place-items-center rounded-full'
							title={messages.removeValue}
							aria-label={messages.actionLabel(messages.removeValue, label)}
							disabled={disabled}
							onClick={() => onChange(values.filter((_, itemIndex) => itemIndex !== index))}
						>
							<X aria-hidden='true' className='size-3' />
						</button>
					</span>
				);
			})}
		</div>
	);
}

function queryOptionKey(option: { label: string; value: QueryJsonPrimitive }) {
	return `${queryValueKey(option.value)}:${option.label}`;
}

function queryValueKey(value: QueryJsonValue): string {
	if (value === null) return 'null';
	if (Array.isArray(value)) return `array:${value.map(queryValueKey).join('|')}`;
	if (typeof value === 'number') {
		if (Object.is(value, -0)) return 'number:-0';
		if (Number.isNaN(value)) return 'number:NaN';
	}
	if (typeof value === 'object') {
		return `object:${Object.keys(value)
			.sort()
			.map((key) => `${key}:${queryValueKey(value[key])}`)
			.join('|')}`;
	}
	return `${typeof value}:${String(value)}`;
}

function withOccurrenceKeys<T>(items: readonly T[], getIdentity: (item: T) => string) {
	const occurrences = new Map<string, number>();
	return items.map((item) => {
		const identity = getIdentity(item);
		const occurrence = occurrences.get(identity) ?? 0;
		occurrences.set(identity, occurrence + 1);
		return { item, key: `${identity}:${occurrence}` };
	});
}

function focusFirstOption(event: ReactKeyboardEvent<HTMLInputElement>, container: HTMLDivElement | null) {
	if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
	event.preventDefault();
	const options = [
		...(container?.querySelectorAll<HTMLButtonElement>('button[data-query-option]:not(:disabled)') ?? []),
	];
	const target = event.key === 'ArrowUp' || event.key === 'End' ? options.at(-1) : options[0];
	target?.focus();
}

function focusAdjacentOption(event: ReactKeyboardEvent<HTMLButtonElement>) {
	if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
	const container = event.currentTarget.closest<HTMLElement>('[data-query-options]');
	const options = [
		...(container?.querySelectorAll<HTMLButtonElement>('button[data-query-option]:not(:disabled)') ?? []),
	];
	const current = options.indexOf(event.currentTarget);
	if (current < 0 || options.length === 0) return;
	event.preventDefault();
	const target =
		event.key === 'Home'
			? 0
			: event.key === 'End'
				? options.length - 1
				: (current + (event.key === 'ArrowDown' ? 1 : -1) + options.length) % options.length;
	options[target]?.focus();
}

function inputType(kind: QueryFieldKind) {
	if (kind === 'number' || kind === 'integer') return 'number';
	if (kind === 'date') return 'date';
	if (kind === 'datetime') return 'datetime-local';
	return 'text';
}

function parseScalar(value: string, kind: QueryFieldKind): QueryJsonPrimitive {
	if (!value.trim()) return null;
	if (kind === 'number' || kind === 'integer') {
		const parsed = Number(value);
		return Number.isFinite(parsed) && (kind !== 'integer' || Number.isInteger(parsed)) ? parsed : null;
	}
	if (kind === 'boolean') return value === 'true' ? true : value === 'false' ? false : null;
	if (kind === 'datetime') {
		const parsed = new Date(value);
		return Number.isFinite(parsed.getTime()) ? parsed.toISOString() : null;
	}
	return value;
}

function formatEditorValue(value: QueryJsonValue, kind: QueryFieldKind) {
	if (kind !== 'datetime' || typeof value !== 'string') return formatScalar(value);
	const parsed = new Date(value);
	if (!Number.isFinite(parsed.getTime())) return '';
	const local = new Date(parsed.getTime() - parsed.getTimezoneOffset() * 60_000);
	return local.toISOString().slice(0, 19);
}

function formatScalar(value: QueryJsonValue) {
	return typeof value === 'string' || typeof value === 'number' ? String(value) : '';
}

import { ArrowDown, ArrowUp, ChevronDown, ChevronRight, Copy, Layers3, Plus, Trash2 } from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useId, useMemo, useState } from 'react';
import { cn } from '@/lib/utils';
import type { QueryValueEditorComponent, QueryValueEditorProps, QueryValueEditorRenderer } from './query-editors';
import { QueryDefaultValueEditor, QueryFieldPicker } from './query-editors';
import type { QueryBuilderMessages } from './query-messages';
import { defaultQueryBuilderMessages } from './query-messages';
import type { QueryField, QueryGroup, QueryIdFactory, QueryNode, QueryOperator, QueryRule } from './query-model';
import {
	createQueryGroup,
	createQueryId,
	createQueryRuleForField,
	defaultQueryOperators,
	getDefaultValueForOperator,
	getOperatorsForField,
} from './query-model';
import type { QueryAction, QueryValidationIssue } from './query-state';
import { cloneQueryNode, countQueryRules, isQueryGroupValue, validateQuery } from './query-state';
import { useQueryBuilderController } from './use-query-builder';

export type QueryBuilderHeadingLevel = 'h2' | 'h3' | 'h4';

export type QueryBuilderProps = Omit<ComponentPropsWithRef<'section'>, 'onChange' | 'title'> & {
	query: QueryGroup;
	fields: readonly QueryField[];
	operators?: readonly QueryOperator[];
	onQueryChange: (query: QueryGroup, action: QueryAction) => void;
	title?: ReactNode;
	description?: ReactNode;
	actions?: ReactNode;
	headingLevel?: QueryBuilderHeadingLevel;
	messages?: Partial<QueryBuilderMessages>;
	valueEditors?: Readonly<Record<string, QueryValueEditorComponent>>;
	renderValueEditor?: QueryValueEditorRenderer;
	createId?: QueryIdFactory;
	maxDepth?: number;
	readOnly?: boolean;
	disabled?: boolean;
	showValidation?: boolean;
};

type BuilderContext = {
	fields: readonly QueryField[];
	fieldMap: ReadonlyMap<string, QueryField>;
	operators: readonly QueryOperator[];
	operatorMap: ReadonlyMap<string, QueryOperator>;
	messages: QueryBuilderMessages;
	issuesByNode: ReadonlyMap<string, readonly QueryValidationIssue[]>;
	valueEditors?: Readonly<Record<string, QueryValueEditorComponent>>;
	renderValueEditor?: QueryValueEditorRenderer;
	createId: QueryIdFactory;
	maxDepth: number;
	readOnly: boolean;
	disabled: boolean;
	showValidation: boolean;
	instanceId: string;
	dispatch: (action: QueryAction) => QueryGroup;
	collapsed: ReadonlySet<string>;
	toggleCollapsed: (id: string) => void;
};

export function QueryBuilder({
	query,
	fields,
	operators = defaultQueryOperators,
	onQueryChange,
	title,
	description,
	actions,
	headingLevel: Heading = 'h2',
	messages: messageOverrides,
	valueEditors,
	renderValueEditor,
	createId = createQueryId,
	maxDepth = 4,
	readOnly = false,
	disabled = false,
	showValidation = true,
	className,
	'aria-label': ariaLabel,
	...props
}: QueryBuilderProps) {
	const instanceId = useId();
	const messages = useMemo(() => ({ ...defaultQueryBuilderMessages, ...messageOverrides }), [messageOverrides]);
	const effectiveMaxDepth = Number.isInteger(maxDepth) && maxDepth >= 0 ? Math.min(maxDepth, 64) : 4;
	const reducerOptions = useMemo(() => ({ maxDepth: effectiveMaxDepth }), [effectiveMaxDepth]);
	const { dispatch } = useQueryBuilderController({ query, onQueryChange, reducerOptions });
	const fieldMap = useMemo(() => new Map(fields.map((field) => [field.name, field])), [fields]);
	const operatorMap = useMemo(() => new Map(operators.map((operator) => [operator.name, operator])), [operators]);
	const queryIsValid = useMemo(() => isQueryGroupValue(query), [query]);
	const issues = useMemo(
		() =>
			showValidation
				? validateQuery(query, { fields, operators, maxDepth: effectiveMaxDepth }).map((issue) => ({
						...issue,
						message: messages.validationIssue(issue),
					}))
				: [],
		[effectiveMaxDepth, fields, messages, operators, query, showValidation],
	);
	const issuesByNode = useMemo(() => {
		const map = new Map<string, QueryValidationIssue[]>();
		for (const issue of issues) map.set(issue.nodeId, [...(map.get(issue.nodeId) ?? []), issue]);
		return map;
	}, [issues]);
	const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set());
	const context: BuilderContext = {
		fields,
		fieldMap,
		operators,
		operatorMap,
		messages,
		issuesByNode,
		valueEditors,
		renderValueEditor,
		createId,
		maxDepth: effectiveMaxDepth,
		readOnly,
		disabled,
		showValidation,
		instanceId,
		dispatch,
		collapsed,
		toggleCollapsed: (id) =>
			setCollapsed((current) => {
				const next = new Set(current);
				if (next.has(id)) next.delete(id);
				else next.add(id);
				return next;
			}),
	};
	const ruleCount = queryIsValid ? countQueryRules(query) : 0;
	return (
		<section
			data-slot='query-builder'
			data-valid={queryIsValid && issues.length === 0 ? 'true' : 'false'}
			aria-label={ariaLabel ?? (typeof title === 'string' ? title : messages.title)}
			data-readonly={readOnly || undefined}
			className={cn('border-base-300 bg-base-100 min-w-0 overflow-hidden rounded-md border', className)}
			{...props}
		>
			<header className='border-base-300 bg-base-200/35 flex min-h-14 flex-wrap items-start gap-3 border-b px-3 py-3 md:px-4'>
				<div className='min-w-0 flex-1'>
					<div className='flex flex-wrap items-center gap-2'>
						<Heading className='text-sm font-semibold'>{title ?? messages.title}</Heading>
						<span className='badge badge-outline badge-sm'>{messages.conditionCount(ruleCount)}</span>
						{issues.length ? (
							<span className='badge badge-warning badge-sm'>{messages.validationCount(issues.length)}</span>
						) : null}
					</div>
					{description ? <div className='text-base-content/65 mt-0.5 text-xs'>{description}</div> : null}
				</div>
				{actions ? (
					<div className='flex w-full max-w-full min-w-0 flex-wrap items-center gap-1 sm:w-auto sm:shrink-0 sm:justify-end'>
						{actions}
					</div>
				) : null}
			</header>
			<div className='p-2 sm:p-3'>
				{queryIsValid ? (
					<QueryBuilderGroup group={query} context={context} depth={0} index={0} siblingCount={1} root />
				) : (
					<div
						className='border-error/40 bg-error/10 text-base-content rounded-sm border px-3 py-4 text-sm'
						role='alert'
					>
						{messages.invalidQuery}
					</div>
				)}
			</div>
			{showValidation ? (
				<div className='sr-only' role='status' aria-live='polite'>
					{issues.length ? messages.validationCount(issues.length) : ''}
				</div>
			) : null}
		</section>
	);
}

type QueryBuilderGroupProps = {
	group: QueryGroup;
	context: BuilderContext;
	depth: number;
	index: number;
	siblingCount: number;
	parentId?: string;
	root?: boolean;
};

function QueryBuilderGroup({
	group,
	context,
	depth,
	index,
	siblingCount,
	parentId,
	root = false,
}: QueryBuilderGroupProps) {
	const { messages } = context;
	const collapsed = context.collapsed.has(group.id);
	const locked = context.disabled;
	const groupIssues = context.issuesByNode.get(group.id) ?? [];
	const groupIssueId = useId();
	return (
		<fieldset
			data-slot='query-group'
			data-depth={depth}
			aria-describedby={groupIssues.length ? groupIssueId : undefined}
			className={cn('border-base-300 min-w-0', root ? 'border-0' : 'bg-base-100 rounded-md border border-s-2')}
		>
			<legend className='sr-only'>{messages.conditionCount(countQueryRules(group))}</legend>
			<div className={cn('flex min-h-10 min-w-0 flex-wrap items-center gap-2 px-2 py-1.5', !root && 'bg-base-200/30')}>
				<button
					type='button'
					className='btn btn-ghost btn-xs btn-square'
					title={collapsed ? messages.expandGroup : messages.collapseGroup}
					aria-label={collapsed ? messages.expandGroup : messages.collapseGroup}
					aria-expanded={!collapsed}
					onClick={() => context.toggleCollapsed(group.id)}
				>
					{collapsed ? (
						<ChevronRight aria-hidden='true' className='size-4' />
					) : (
						<ChevronDown aria-hidden='true' className='size-4' />
					)}
				</button>
				<span className='text-base-content/65 text-xs font-medium'>{messages.match}</span>
				{context.readOnly ? (
					<span className='badge badge-outline badge-sm'>
						{group.combinator === 'and' ? messages.all : messages.any}
					</span>
				) : (
					<div role='radiogroup' aria-label={messages.match} className='join'>
						{(['and', 'or'] as const).map((combinator) => (
							<label
								key={combinator}
								className={cn('btn btn-xs join-item min-w-11', group.combinator === combinator && 'btn-active')}
							>
								<input
									type='radio'
									className='sr-only'
									name={`query-combinator-${context.instanceId}-${group.id}`}
									value={combinator}
									checked={group.combinator === combinator}
									disabled={locked}
									onChange={() => context.dispatch({ type: 'update-group', id: group.id, patch: { combinator } })}
								/>
								{combinator === 'and' ? messages.all : messages.any}
							</label>
						))}
					</div>
				)}
				{context.readOnly ? (
					group.negated ? (
						<span className='badge badge-outline badge-sm'>{messages.not}</span>
					) : null
				) : (
					<label className='label text-base-content cursor-pointer gap-1.5 py-0 text-xs'>
						<input
							type='checkbox'
							className='toggle toggle-xs'
							checked={group.negated}
							disabled={locked}
							onChange={(event) =>
								context.dispatch({ type: 'update-group', id: group.id, patch: { negated: event.target.checked } })
							}
						/>
						{messages.not}
					</label>
				)}
				<span className='text-base-content/65 text-[11px]'>{messages.conditionCount(countQueryRules(group))}</span>
				{groupIssues.length ? (
					<span
						className='badge badge-warning badge-xs'
						title={groupIssues[0].message}
						aria-label={groupIssues[0].message}
					>
						{groupIssues.length}
					</span>
				) : null}
				<div className='min-w-2 flex-1' />
				{!root && parentId && !context.readOnly ? (
					<NodeActions node={group} parentId={parentId} context={context} index={index} siblingCount={siblingCount} />
				) : null}
			</div>
			{context.showValidation && groupIssues.length ? (
				<div
					id={groupIssueId}
					className='border-warning/40 bg-warning/15 text-base-content mx-2 mb-1 rounded-sm border px-2 py-1 text-xs'
					role='alert'
				>
					{groupIssues[0].message}
				</div>
			) : null}
			{!collapsed ? (
				<div className={cn('min-w-0 space-y-2', root ? 'pt-1' : 'p-2')}>
					{group.children.length === 0 ? (
						<div className='border-base-300 text-base-content/65 rounded-sm border border-dashed px-3 py-8 text-center text-sm'>
							{messages.emptyGroup}
						</div>
					) : (
						group.children.map((child, childIndex) =>
							child.type === 'group' ? (
								<QueryBuilderGroup
									key={child.id}
									group={child}
									context={context}
									depth={depth + 1}
									index={childIndex}
									siblingCount={group.children.length}
									parentId={group.id}
								/>
							) : (
								<QueryBuilderRule
									key={child.id}
									rule={child}
									parentId={group.id}
									context={context}
									index={childIndex}
									siblingCount={group.children.length}
								/>
							),
						)
					)}
					{!context.readOnly ? (
						<div className='flex flex-wrap items-center gap-2 pt-1'>
							<QueryFieldPicker
								fields={context.fields}
								label={
									<>
										<Plus aria-hidden='true' className='size-3.5' /> {messages.addCondition}
									</>
								}
								searchLabel={messages.searchFields}
								emptyLabel={messages.noFields}
								disabled={context.disabled}
								onSelect={(field) =>
									context.dispatch({
										type: 'insert-node',
										parentId: group.id,
										node: createQueryRuleForField(field, context.createId('rule'), context.operators),
									})
								}
							/>
							<button
								type='button'
								className='btn btn-ghost btn-sm'
								disabled={context.disabled || depth >= context.maxDepth}
								onClick={() =>
									context.dispatch({
										type: 'insert-node',
										parentId: group.id,
										node: createQueryGroup(context.createId('group')),
									})
								}
							>
								<Layers3 aria-hidden='true' className='size-4' />
								{messages.addGroup}
							</button>
						</div>
					) : null}
				</div>
			) : null}
		</fieldset>
	);
}

type QueryBuilderRuleProps = {
	rule: QueryRule;
	parentId: string;
	context: BuilderContext;
	index: number;
	siblingCount: number;
};

function QueryBuilderRule({ rule, parentId, context, index, siblingCount }: QueryBuilderRuleProps) {
	const field = context.fieldMap.get(rule.field);
	const availableOperators = field ? getOperatorsForField(field, context.operators) : [];
	const operator = context.operatorMap.get(rule.operator);
	const operatorAllowed = Boolean(operator && availableOperators.some((candidate) => candidate.name === operator.name));
	const issues = context.issuesByNode.get(rule.id) ?? [];
	const invalid = issues.length > 0;
	const locked = context.disabled;
	const editorId = useId();
	const issueId = `${editorId}-issues`;
	return (
		<div
			data-slot='query-rule'
			data-rule-id={rule.id}
			role='group'
			aria-label={field ? context.messages.conditionLabel(field.label) : context.messages.queryCondition}
			tabIndex={context.readOnly ? 0 : undefined}
			className={cn(
				'border-base-300 bg-base-100 grid min-w-0 gap-2 rounded-md border p-2',
				'lg:grid-cols-[minmax(9rem,.9fr)_minmax(9rem,.75fr)_minmax(12rem,1.4fr)_auto] lg:items-start',
				invalid && 'border-warning/60',
			)}
		>
			<div className='min-w-0'>
				<span className='text-base-content/65 mb-1 block text-[11px] lg:sr-only'>{context.messages.chooseField}</span>
				{context.readOnly ? (
					<output className='border-base-300 flex min-h-8 w-full items-center rounded-sm border px-2.5 text-sm'>
						{field?.label ?? context.messages.unknownField}
					</output>
				) : (
					<QueryFieldPicker
						fields={context.fields}
						label={field?.label ?? context.messages.unknownField}
						searchLabel={context.messages.searchFields}
						emptyLabel={context.messages.noFields}
						disabled={locked}
						invalid={!field}
						ariaDescribedBy={invalid ? issueId : undefined}
						className='w-full'
						onSelect={(nextField) => {
							const nextRule = createQueryRuleForField(nextField, rule.id, context.operators);
							context.dispatch({
								type: 'update-rule',
								id: rule.id,
								patch: { field: nextRule.field, operator: nextRule.operator, value: nextRule.value },
							});
						}}
					/>
				)}
			</div>
			<div className='min-w-0'>
				<span className='text-base-content/65 mb-1 block text-[11px] lg:sr-only'>
					{context.messages.chooseOperator}
				</span>
				{context.readOnly ? (
					<output className='border-base-300 flex min-h-8 w-full items-center rounded-sm border px-2.5 text-sm'>
						{operatorAllowed
							? operator?.label
							: context.messages.unavailableOperator(operator?.label ?? context.messages.unknownOperator)}
					</output>
				) : (
					<select
						className='select select-bordered select-sm w-full min-w-0'
						aria-label={context.messages.chooseOperator}
						aria-invalid={!operatorAllowed || undefined}
						aria-describedby={invalid ? issueId : undefined}
						disabled={locked || !field}
						value={rule.operator}
						onChange={(event) => {
							if (!field) return;
							const nextOperator = context.operatorMap.get(event.target.value);
							if (!nextOperator) return;
							context.dispatch({
								type: 'update-rule',
								id: rule.id,
								patch: { operator: nextOperator.name, value: getDefaultValueForOperator(field, nextOperator) },
							});
						}}
					>
						{!operatorAllowed ? (
							<option value={rule.operator} disabled>
								{context.messages.unavailableOperator(operator?.label ?? context.messages.unknownOperator)}
							</option>
						) : null}
						{availableOperators.map((candidate) => (
							<option key={candidate.name} value={candidate.name}>
								{candidate.label}
							</option>
						))}
					</select>
				)}
			</div>
			<div className='min-w-0'>
				<span className='text-base-content/65 mb-1 block text-[11px] lg:sr-only'>{context.messages.chooseValue}</span>
				{field && operator ? (
					renderEditor({ context, editorId, issueId, field, operator, rule, invalid, locked })
				) : (
					<div className='bg-base-200 h-8 rounded-sm' />
				)}
			</div>
			{!context.readOnly ? (
				<NodeActions node={rule} parentId={parentId} context={context} index={index} siblingCount={siblingCount} />
			) : null}
			{context.showValidation && issues.length ? (
				<div
					className='border-warning/40 bg-warning/15 text-base-content col-span-full min-w-0 rounded-sm border px-2 py-1 text-xs'
					id={issueId}
					role='alert'
				>
					{issues[0].message}
				</div>
			) : null}
		</div>
	);
}

function renderEditor({
	context,
	editorId,
	issueId,
	field,
	operator,
	rule,
	invalid,
	locked,
}: {
	context: BuilderContext;
	editorId: string;
	issueId: string;
	field: QueryField;
	operator: QueryOperator;
	rule: QueryRule;
	invalid: boolean;
	locked: boolean;
}) {
	const props: QueryValueEditorProps = {
		id: editorId,
		rule,
		field,
		operator,
		value: rule.value,
		disabled: locked,
		readOnly: context.readOnly,
		invalid,
		ariaDescribedBy: invalid ? issueId : undefined,
		messages: context.messages,
		onChange: (value) => context.dispatch({ type: 'update-rule', id: rule.id, patch: { value } }),
	};
	const rendered = context.renderValueEditor?.(props);
	if (rendered !== undefined) return rendered;
	const getEditor = (name: string | undefined) =>
		name && context.valueEditors && Object.hasOwn(context.valueEditors, name) ? context.valueEditors[name] : undefined;
	const Editor = getEditor(field.editor) ?? getEditor(operator.editor);
	return Editor ? <Editor {...props} /> : <QueryDefaultValueEditor {...props} />;
}

function NodeActions({
	node,
	parentId,
	context,
	index,
	siblingCount,
}: {
	node: QueryNode;
	parentId: string;
	context: BuilderContext;
	index: number;
	siblingCount: number;
}) {
	const nodeLabel =
		node.type === 'rule'
			? (context.fieldMap.get(node.field)?.label ?? context.messages.queryCondition)
			: messagesForGroup(context.messages, countQueryRules(node));
	const actionLabel = (label: string) => context.messages.actionLabel(label, nodeLabel);
	return (
		<div
			className='flex shrink-0 items-center justify-end gap-0.5 lg:self-center'
			role='toolbar'
			aria-label={context.messages.actionsLabel(nodeLabel)}
		>
			<ActionButton
				label={actionLabel(context.messages.moveUp)}
				disabled={context.disabled || index === 0}
				onClick={() => context.dispatch({ type: 'move-node', id: node.id, direction: 'up' })}
			>
				<ArrowUp aria-hidden='true' className='size-3.5' />
			</ActionButton>
			<ActionButton
				label={actionLabel(context.messages.moveDown)}
				disabled={context.disabled || index >= siblingCount - 1}
				onClick={() => context.dispatch({ type: 'move-node', id: node.id, direction: 'down' })}
			>
				<ArrowDown aria-hidden='true' className='size-3.5' />
			</ActionButton>
			<ActionButton
				label={actionLabel(context.messages.duplicate)}
				disabled={context.disabled}
				onClick={() =>
					context.dispatch({
						type: 'insert-node',
						parentId,
						index: index + 1,
						node: cloneQueryNode(node, context.createId),
					})
				}
			>
				<Copy aria-hidden='true' className='size-3.5' />
			</ActionButton>
			<ActionButton
				label={actionLabel(context.messages.remove)}
				disabled={context.disabled}
				danger
				onClick={() => context.dispatch({ type: 'remove-node', id: node.id })}
			>
				<Trash2 aria-hidden='true' className='size-3.5' />
			</ActionButton>
		</div>
	);
}

function messagesForGroup(messages: QueryBuilderMessages, count: number) {
	return messages.groupLabel(count);
}

function ActionButton({
	label,
	disabled,
	danger,
	onClick,
	children,
}: {
	label: string;
	disabled?: boolean;
	danger?: boolean;
	onClick: () => void;
	children: ReactNode;
}) {
	return (
		<button
			type='button'
			className={cn('btn btn-ghost btn-sm btn-square lg:btn-xs', danger && 'text-error')}
			title={label}
			aria-label={label}
			disabled={disabled}
			onClick={onClick}
		>
			{children}
		</button>
	);
}

